"""A small in-process cache whose entries expire."""
import time


class TTLCache:
    def __init__(self, ttl, maxsize=128, sliding=False, clock=time.monotonic):
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        if maxsize < 1:
            raise ValueError("maxsize must be at least 1")
        self._ttl = ttl
        self._maxsize = maxsize
        self._sliding = sliding
        self._clock = clock
        self._items = {}

    def _purge(self, now):
        dead = [k for k, e in self._items.items() if e[1] <= now]
        for k in dead:
            del self._items[k]

    def set(self, key, value, ttl=None):
        life = self._ttl if ttl is None else ttl
        if life <= 0:
            raise ValueError("ttl must be positive")
        now = self._clock()
        self._purge(now)
        if key in self._items:
            del self._items[key]
        elif len(self._items) >= self._maxsize:
            oldest = next(iter(self._items))
            del self._items[oldest]
        self._items[key] = [value, now + life, life]

    def get(self, key, default=None):
        now = self._clock()
        entry = self._items.get(key)
        if entry is None:
            return default
        if entry[1] <= now:
            del self._items[key]
            return default
        if self._sliding:
            entry[1] = now + entry[2]
        del self._items[key]
        self._items[key] = entry
        return entry[0]

    def remaining(self, key):
        entry = self._items.get(key)
        if entry is None:
            return None
        left = entry[1] - self._clock()
        if left <= 0:
            return None
        return left

    def __len__(self):
        self._purge(self._clock())
        return len(self._items)

    def __contains__(self, key):
        entry = self._items.get(key)
        return entry is not None and entry[1] > self._clock()

