"""A circuit breaker."""
import time

CLOSED = "closed"
OPEN = "open"
HALF_OPEN = "half-open"


class CircuitBreaker:
    def __init__(self, failure_threshold=3, cooldown=30, success_threshold=1, clock=time.monotonic):
        if failure_threshold < 1 or success_threshold < 1:
            raise ValueError("thresholds must be at least 1")
        if cooldown <= 0:
            raise ValueError("cooldown must be positive")
        self._fail_limit = failure_threshold
        self._cooldown = cooldown
        self._succ_limit = success_threshold
        self._clock = clock
        self._state = CLOSED
        self._failures = 0
        self._successes = 0
        self._opened_at = 0.0
        self._probing = False

    def _refresh(self):
        if self._state == OPEN and self._clock() - self._opened_at >= self._cooldown:
            self._state = HALF_OPEN
            self._successes = 0
            self._probing = False

    def _trip(self):
        self._state = OPEN
        self._opened_at = self._clock()
        self._failures = 0
        self._probing = False

    @property
    def state(self):
        self._refresh()
        return self._state

    def allow(self):
        self._refresh()
        if self._state == CLOSED:
            return True
        if self._state == OPEN:
            return False
        if self._probing:
            return False
        self._probing = True
        return True

    def record_success(self):
        self._refresh()
        if self._state == CLOSED:
            self._failures = 0
        elif self._state == HALF_OPEN:
            self._probing = False
            self._successes += 1
            if self._successes >= self._succ_limit:
                self._state = CLOSED
                self._failures = 0

    def record_failure(self):
        self._refresh()
        if self._state == CLOSED:
            self._failures += 1
            if self._failures >= self._fail_limit:
                self._trip()
        elif self._state == HALF_OPEN:
            self._trip()

    def retry_in(self):
        self._refresh()
        if self._state != OPEN:
            return 0.0
        return self._opened_at + self._cooldown - self._clock()

